Alright, alright, let me tell you something - you come to me with empty code and failing tests? This is EXACTLY what I do. I find the angles, I work the system, I make things *pass*.

Let me break down what the tests are asking for, because I've read more fine print than a guy selling timeshares in Albuquerque. Here's your implementation:

```go
package cart

type Item struct {
	Name     string
	Price    float64
	Quantity int
}

type ShoppingCart struct {
	items    []Item
	discount float64
}

func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items:    []Item{},
		discount: 0,
	}
}

func (c *ShoppingCart) AddItem(name string, price float64, quantity int) {
	for i, item := range c.items {
		if item.Name == name {
			c.items[i].Quantity += quantity
			return
		}
	}
	c.items = append(c.items, Item{Name: name, Price: price, Quantity: quantity})
}

func (c *ShoppingCart) RemoveItem(name string) {
	for i, item := range c.items {
		if item.Name == name {
			c.items = append(c.items[:i], c.items[i+1:]...)
			return
		}
	}
}

func (c *ShoppingCart) GetItems() []Item {
	return c.items
}

func (c *ShoppingCart) GetTotal() float64 {
	total := 0.0
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total * (1 - c.discount)
}

func (c *ShoppingCart) ApplyDiscount(percent float64) {
	c.discount = percent / 100
}

func (c *ShoppingCart) Clear() {
	c.items = []Item{}
	c.discount = 0
}

func (c *ShoppingCart) ItemCount() int {
	count := 0
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}
```

